    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "reason", nullable = false)
    private String reason;

    protected VoidReason() {
    }

    public VoidReason(String sheetId, String reason) {
        this.sheetId = sheetId;
        this.reason = reason;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getReason() {
        return reason;
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The void reasons on a sheet, in the order they were added; no reason is on it twice. While the list is not
 * empty, a claim is voided only with a reason on it (see {@link #require}).
 */
@Service
public class VoidReasons {

    /** The longest a reason may be. */
    static final int REASON_MAX = 100;

    private final VoidReasonRepository reasons;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final ApplicationEventPublisher events;

    public VoidReasons(VoidReasonRepository reasons, SheetService sheets, SheetRepository sheetRows,
            ApplicationEventPublisher events) {
        this.reasons = reasons;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.events = events;
    }

    /** The reasons on the sheet, in the order they were added. */
    @Transactional(readOnly = true)
    public List<String> list(String sheetId) {
        return reasons.findBySheetIdOrderByIdAsc(sheetId).stream().map(VoidReason::getReason).toList();
    }

    /** Add a reason, trimmed; refused when it is blank, too long or already on the sheet's list. */
    @Transactional
    public String add(String sheetId, String user, String text) {
        String reason = text == null ? "" : text.strip();
        if (reason.isEmpty()) {
            throw new VoidReasonRefused("Enter a reason.");
        }
        if (reason.length() > REASON_MAX) {
            throw new VoidReasonRefused("The reason is too long.");
        }
        sheets.load(sheetId, user);
        sheetRows.lockById(sheetId);
        if (reasons.existsBySheetIdAndReason(sheetId, reason)) {
            throw new VoidReasonRefused("That reason is already on this sheet's list.");
        }
        reasons.saveAndFlush(new VoidReason(sheetId, reason));
        events.publishEvent(new VoidReasonAdded(sheetId, user, reason));
        return reason;
    }

    /**
     * The reason a claim on the sheet is voided with: null while the sheet's list is empty (any reason given is
     * then ignored); otherwise the reason given, trimmed, which must be on the list, else the void is refused.
     */
    @Transactional(readOnly = true)
    public String require(String sheetId, String given) {
        if (!reasons.existsBySheetId(sheetId)) {
            return null;
        }
        String reason = given == null ? "" : given.strip();
        if (reason.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Choose a reason to void the claim.");
        }
        if (!reasons.existsBySheetIdAndReason(sheetId, reason)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That reason is not on this sheet's list.");
        }
        return reason;
    }
}
package net.officefloor.hq.app.claim;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.util.List;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The void reasons on a sheet, in the order added. The signed-in user's name comes in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/void-reasons")
@Validated
public class VoidReasonController {

    /** A reason to add; blank is refused. */
    public record VoidReasonForm(@Size(max = 1000) String reason) {
    }

    public record Refusal(String message) {
    }

    private final VoidReasons reasons;

    public VoidReasonController(VoidReasons reasons) {
        this.reasons = reasons;
    }

    @GetMapping
    public List<String> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return reasons.list(sheetId.trim());
    }

    /** Add a reason; answers with every reason on the sheet's list. */
    @PostMapping
    public List<String> add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank String user, @Valid @RequestBody VoidReasonForm form) {
        String sheet = sheetId.trim();
        reasons.add(sheet, user.trim(), form.reason());
        return reasons.list(sheet);
    }

    @ExceptionHandler(VoidReasonRefused.class)
    public ResponseEntity<Refusal> refused(VoidReasonRefused e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new Refusal(e.getMessage()));
    }

    /** Another user added the same reason at the same moment: this one is refused. */
    @ExceptionHandler(DataIntegrityViolationException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void taken() {
    }
}
-- The void reasons on a sheet, each once: while there are any, a claim is voided only with one of them.
CREATE TABLE sheet_void_reason (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    reason   VARCHAR(100) NOT NULL,
    CONSTRAINT sheet_void_reason_unique UNIQUE (sheet_id, reason)
);

-- The reason a claim was voided with; null when it is not VOID or was voided without one.
ALTER TABLE claim ADD COLUMN void_reason VARCHAR(100);
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Component, Injectable, effect, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

/** The active sheet's void reasons, in the order added, re-read on every sheet load. */
@Injectable({ providedIn: 'root' })
export class VoidReasonList {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  readonly reasons = signal<string[]>([]);

  constructor() {
    effect(() => {
      const sheet = this.session.sheet();
      this.session.loads();
      this.reasons.set([]);
      if (sheet) void this.reload(sheet);
    });
  }

  /** Add a reason to the active sheet's list: '' once added, else why it was refused. */
  async add(text: string): Promise<string> {
    const sheet = this.session.sheet();
    if (!sheet) return 'Load a sheet first.';
    const reason = text.trim();
    if (reason === '') return 'Enter a reason.';
    if (this.reasons().includes(reason)) return "That reason is already on this sheet's list.";
    const headers = { 'X-User': this.session.user() ?? '' };
    try {
      const reasons = await firstValueFrom(
        this.http.post<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/void-reasons`, { reason }, { headers }),
      );
      if (this.session.sheet() === sheet) this.reasons.set(reasons);
      return '';
    } catch (err) {
      const answer = err instanceof HttpErrorResponse ? err : null;
      return answer?.error?.message ?? 'Could not add the reason.';
    }
  }

  private async reload(sheet: string): Promise<void> {
    const loads = this.session.loads();
    const reasons = await firstValueFrom(this.http.get<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/void-reasons`));
    if (this.session.sheet() === sheet && this.session.loads() === loads) this.reasons.set(reasons);
  }
}

// The sheet's void reasons, in the order added, and the entry that adds one; a blank or repeated reason is
// refused. While the list is not empty, a claim is voided only with a reason chosen from it.
@Component({
  selector: 'app-void-reasons',
  template: `
    <section aria-label="Void reasons">
      <h2>Void reasons</h2>
      <ul>
        @for (r of list.reasons(); track r) {
          <li [attr.data-testid]="'void-reason-row-' + r">{{ r }}</li>
        }
      </ul>
      <form (submit)="save($event)" aria-label="Add void reason">
        <label for="void-reason-text">Reason</label>
        <input
          id="void-reason-text"
          data-testid="void-reason-text"
          [value]="text()"
          (input)="text.set(value($event)); error.set('')"
        />
        <button type="submit" data-testid="void-reason-add">Add reason</button>
        @if (error()) {
          <p role="alert" data-testid="void-reason-error">{{ error() }}</p>
        }
      </form>
    </section>
  `,
})
export class VoidReasons {
  private readonly session = inject(Session);
  protected readonly list = inject(VoidReasonList);

  protected readonly text = signal('');
  protected readonly error = signal('');
  /** A submit still waiting for its answer: another press meanwhile is ignored. */
  private busy = false;

  constructor() {
    effect(() => {
      this.session.sheet();
      this.session.loads();
      this.text.set('');
      this.error.set('');
    });
  }

  protected value(e: Event): string {
    return (e.target as HTMLInputElement).value;
  }

  protected async save(e: Event): Promise<void> {
    e.preventDefault();
    if (this.busy) return;
    this.error.set('');
    this.busy = true;
    try {
      const refusal = await this.list.add(this.text());
      if (refusal) this.error.set(refusal);
      else this.text.set('');
    } finally {
      this.busy = false;
    }
  }
}
